// Regenerate everything derived from the structured data (data/games,
// data/open, data/engines, data/progress.yaml):
//
//   README.md            the generated regions (family index, recent progress)
//   games/*.md           one page per game
//   families/*.md        one page per family
//   pages/*.md           open problems, engines
//
// Rendering lives in scripts/pages.ts; this file writes the output and, with
// --check, fails when any generated file is out of date or a stray .md file
// sits in a generated directory.
//
//   npm run build     # rewrite in place
//   npm run check     # exit non-zero if anything is out of date (for CI)
//
// Runs on Node's native TypeScript support (Node >= 23). Only dependency: `yaml`.

import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { resolveToday } from './open-entries.ts'
import { loadData, render } from './pages.ts'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const README = join(ROOT, 'README.md')

function spliceRegion(md: string, region: string, body: string): string {
  const begin = new RegExp(`(<!-- BEGIN GENERATED:${region}[^>]*-->\\n)[\\s\\S]*?(\\n<!-- END GENERATED:${region} -->)`)
  if (!begin.test(md)) throw new Error(`marker region "${region}" not found in README.md`)
  // Function replacer: a `$` in the body must not be read as a group reference.
  return md.replace(begin, (_m, open: string, close: string) => `${open}${body}${close}`)
}

const data = loadData(ROOT)
const { pages, regions, generatedDirs, warnings } = render(data, resolveToday())
for (const w of warnings) console.warn(`warning: ${w}`)

const outputs = new Map<string, string>(pages)
let readme = readFileSync(README, 'utf8')
const readmeBefore = readme
for (const [region, body] of regions) readme = spliceRegion(readme, region, body)
outputs.set('README.md', readme)

const read = (rel: string) => (existsSync(join(ROOT, rel)) ? readFileSync(join(ROOT, rel), 'utf8') : null)
const changed = [...outputs].filter(([rel, body]) => (rel === 'README.md' ? readmeBefore : read(rel)) !== body).map(([rel]) => rel)
const stray = generatedDirs.flatMap((dir) =>
  existsSync(join(ROOT, dir))
    ? readdirSync(join(ROOT, dir)).filter((f) => f.endsWith('.md')).map((f) => `${dir}/${f}`).filter((rel) => !outputs.has(rel))
    : [],
)

const summary = `${data.games.filter((g) => g.verified).length} verified games, ${data.open.length} open entries, ${data.engines.length} engines; ${outputs.size} files`

if (process.argv.includes('--check')) {
  const problems = [...changed.map((f) => `out of date: ${f}`), ...stray.map((f) => `not generated by any record: ${f}`)]
  if (problems.length) {
    console.error(`Generated pages are out of date — run \`npm run build\`.\n${problems.map((p) => `  - ${p}`).join('\n')}`)
    process.exit(1)
  }
  console.log(`Generated pages up to date (${summary}).`)
} else {
  for (const rel of changed) {
    mkdirSync(dirname(join(ROOT, rel)), { recursive: true })
    writeFileSync(join(ROOT, rel), outputs.get(rel)!)
  }
  // A page whose record was removed or renamed is left for a person to delete;
  // --check fails until they do.
  for (const rel of stray) console.warn(`warning: ${rel} matches no record; delete it`)
  console.log(
    changed.length || stray.length
      ? `Wrote ${changed.length} file(s) (${summary}).`
      : `No change (${summary}).`,
  )
}
